diff --git a/src/main/java/hotel/documents/BookingReceiptLayout.java b/src/main/java/hotel/documents/BookingReceiptLayout.java
new file mode 100644
index 0000000..9a7629c
--- /dev/null
+++ b/src/main/java/hotel/documents/BookingReceiptLayout.java
@@ -0,0 +1,46 @@
+package hotel.documents;
+
+import hotel.reservations.Guest;
+import hotel.reservations.Reservation;
+import hotel.rooms.Room;
+import java.math.BigDecimal;
+import java.time.LocalDate;
+import java.util.Locale;
+
+/** The receipt in English, for foreign guests. */
+class BookingReceiptLayout implements DocumentLayout {
+
+    @Override
+    public String title() {
+        return "Booking receipt";
+    }
+
+    @Override
+    public String text(Reservation reservation, Room room) {
+        var price = reservation.price();
+        Guest guest = reservation.guest();
+        int nights = price.nights();
+        StringBuilder text = new StringBuilder();
+        text.append(title()).append(" no. ").append(reservation.id()).append('\n');
+        text.append("Guest: ").append(guest.name())
+                .append(" (passport ").append(guest.passport()).append(", ").append(guest.country()).append(")\n");
+        text.append("Room: ").append(room.number()).append(" (").append(room.type()).append(")\n");
+        text.append("Check-in: ").append(date(reservation.checkIn()))
+                .append(" | Check-out: ").append(date(reservation.checkOut()))
+                .append(" | ").append(nights).append(nights == 1 ? " night" : " nights").append('\n');
+        text.append("Nights: ").append(money(price.subtotal())).append('\n');
+        if (price.discount().signum() > 0) {
+            text.append("Discount: ").append(money(price.discount())).append('\n');
+        }
+        text.append("Total: ").append(money(price.total())).append('\n');
+        return text.toString();
+    }
+
+    private static String money(BigDecimal amount) {
+        return "BRL " + String.format(Locale.US, "%,.2f", amount);
+    }
+
+    private static String date(LocalDate date) {
+        return date.toString();
+    }
+}
diff --git a/src/main/java/hotel/documents/DocumentLayout.java b/src/main/java/hotel/documents/DocumentLayout.java
new file mode 100644
index 0000000..f0d3788
--- /dev/null
+++ b/src/main/java/hotel/documents/DocumentLayout.java
@@ -0,0 +1,22 @@
+package hotel.documents;
+
+import hotel.reservations.Guest;
+import hotel.reservations.Identification;
+import hotel.reservations.Reservation;
+import hotel.rooms.Room;
+
+/** One kind of document: its title and how it reads. Each kind of guest identification has its own. */
+interface DocumentLayout {
+
+    String title();
+
+    String text(Reservation reservation, Room room);
+
+    static DocumentLayout forGuest(Guest guest) {
+        return switch (guest.identification()) {
+            case Identification.Cpf cpf -> new PortugueseReceiptLayout();
+            case Identification.Company company -> new LodgingInvoiceLayout();
+            case Identification.Foreigner foreigner -> new BookingReceiptLayout();
+        };
+    }
+}
